# RemoteOS MCP - enroll this Windows box with dev1 (#101): the ONE fixed line of the README.
# Usage (PowerShell): irm https://raw.githubusercontent.com/zbynekdrlik/remoteos-mcp/main/enroll.ps1 | iex
# Generated by scripts/build_installers.py from installers/enroll-ps1/: edit the parts, not this file.

$ErrorActionPreference = "Stop"
# Public constants (installers/enroll-values.conf), never a secret: the endpoint only queues the
# registration, and dev1's operator accepts it (remoteos-gateway enroll-accept). So, unlike the
# per-enrollment URL of #26, they may cross the UAC elevation.
$EnrollUrl = '@@ENROLL_URL@@'
$EnrollSshKey = '@@ENROLL_SSH_KEY@@'
$EnrollRaw = 'https://raw.githubusercontent.com/zbynekdrlik/remoteos-mcp'
$EnrollLogTailChars = 200000
